import csv, json, html
from collections import Counter
from pathlib import Path
ROOT=Path(__file__).parent; OUT=ROOT/'reports'; m=json.loads((OUT/'experiment_metrics.json').read_text(encoding='utf-8'))
NAMES={'login_issue':'Login','crash':'Crash','performance':'Performance','payment':'Payment','usability':'Usability','feature_request':'Feature request','positive_experience':'Positive'}
def esc(x): return html.escape(str(x))
def bars(title,labels,values,maximum=None,percent=False):
 width=1120; left=280; right=90; top=92; row=54; height=top+row*len(labels)+64; plot=width-left-right; maximum=maximum or max(values)*1.08 or 1
 out=[f'<svg xmlns="http://www.w3.org/2000/svg" width="{width}" height="{height}" viewBox="0 0 {width} {height}"><rect width="100%" height="100%" fill="#ffffff"/><text x="{left}" y="42" font-family="Arial,sans-serif" font-size="26" font-weight="700" fill="#172b4d">{esc(title)}</text>']
 ticks=5
 for i in range(ticks+1):
  value=maximum*i/ticks; x=left+plot*i/ticks
  label=f'{value:.0%}' if percent else f'{value:.1f}'
  out += [f'<line x1="{x:.1f}" y1="{top-8}" x2="{x:.1f}" y2="{top+row*len(labels)-8}" stroke="#e5eaf0"/>',f'<text x="{x:.1f}" y="{top+row*len(labels)+20}" text-anchor="middle" font-family="Arial,sans-serif" font-size="13" fill="#667085">{label}</text>']
 for i,(label,value) in enumerate(zip(labels,values)):
  y=top+i*row; bar=plot*value/maximum; value_label=f'{value:.1%}' if percent else f'{value:,.0f}'
  out += [f'<text x="{left-16}" y="{y+23}" text-anchor="end" font-family="Arial,sans-serif" font-size="15" fill="#344054">{esc(label)}</text>',f'<rect x="{left}" y="{y}" width="{bar:.1f}" height="30" rx="6" fill="#2878a5"/>',f'<text x="{left+bar+10:.1f}" y="{y+21}" font-family="Arial,sans-serif" font-size="14" font-weight="600" fill="#172b4d">{value_label}</text>']
 out.append('</svg>');return ''.join(out)
word=m['results']['word']; char=m['results']['char']; OUT.joinpath('model_comparison.svg').write_text(bars('Baseline comparison: Accuracy and Macro-F1',['Word n-grams — Accuracy','Word n-grams — Macro-F1','Character n-grams — Accuracy','Character n-grams — Macro-F1'],[word['accuracy'],word['macro_f1'],char['accuracy'],char['macro_f1']],maximum=1,percent=True),encoding='utf-8')
by=m['by_dialect']; names=list(by); vals=[by[n]['macro_f1'] for n in names]; OUT.joinpath('dialect_scores.svg').write_text(bars('Character baseline by dialect: paraphrase test',names,vals,maximum=1,percent=True),encoding='utf-8')
loo=m['leave_one_dialect_out']['char']; OUT.joinpath('dialect_generalization.svg').write_text(bars('Character baseline: leave-one-dialect-out',list(loo),[loo[n]['macro_f1'] for n in loo],maximum=1,percent=True),encoding='utf-8')
counts=m['class_counts']; OUT.joinpath('category_counts.svg').write_text(bars('Synthetic corpus balance by theme',[NAMES[k] for k in counts],list(counts.values()),maximum=max(counts.values())*1.15),encoding='utf-8')
with (OUT/'test_predictions.csv').open(encoding='utf-8-sig') as f: rows=list(csv.DictReader(f))
classes=sorted(counts); cm=Counter((r['actual'],r['predicted']) for r in rows); cell=102; left=230; top=150; w=left+cell*len(classes)+25; h=top+cell*len(classes)+55; mx=max(cm.values())
out=[f'<svg xmlns="http://www.w3.org/2000/svg" width="{w}" height="{h}" viewBox="0 0 {w} {h}"><rect width="100%" height="100%" fill="#ffffff"/><text x="{left}" y="36" font-family="Arial,sans-serif" font-size="23" font-weight="700" fill="#172b4d">Character NB confusion matrix — held-out paraphrases</text><text x="{left}" y="66" font-family="Arial,sans-serif" font-size="13" fill="#667085">Rows: actual theme · Columns: predicted theme</text>']
short={k:NAMES[k] for k in classes}
for i,a in enumerate(classes):
 out.append(f'<text x="{left-12}" y="{top+i*cell+56}" text-anchor="end" font-family="Arial,sans-serif" font-size="13" fill="#344054">{short[a]}</text>')
 out.append(f'<text x="{left+i*cell+cell/2}" y="{top-14}" text-anchor="middle" font-family="Arial,sans-serif" font-size="12" fill="#344054">{short[a]}</text>')
 for j,b in enumerate(classes):
  v=cm[(a,b)]; intensity=int(246-115*v/mx); color=f'rgb({intensity-20},{intensity-5},245)'
  out += [f'<rect x="{left+j*cell}" y="{top+i*cell}" width="{cell}" height="{cell}" fill="{color}" stroke="#ffffff" stroke-width="2"/>',f'<text x="{left+j*cell+cell/2}" y="{top+i*cell+59}" text-anchor="middle" font-family="Arial,sans-serif" font-size="17" font-weight="600" fill="#172b4d">{v}</text>']
out.append('</svg>'); OUT.joinpath('confusion_matrix.svg').write_text(''.join(out),encoding='utf-8')
lines=['# Sada Reviews — Experiment Report','', '## Executive summary',f'We generated **{m["total"]:,} synthetic reviews** balanced across seven themes and seven language/dialect slices. Character n-gram Naive Bayes reached Macro-F1 **{char["macro_f1"]:.3f}** vs **{word["macro_f1"]:.3f}** for word n-grams on the held-out paraphrase test (difference {char["macro_f1"]-word["macro_f1"]:+.3f}). These are baseline results on generated data, not CAMeLBERT results or real-world performance.', '', '## Research question','Do character n-grams handle spelling and dialect variation better than word n-grams for short app reviews?', '', '## Dataset and evaluation design',f'- Total: {m["total"]:,}; train: {m["train"]:,}; test: {m["test"]:,}.','- Seven balanced themes and seven slices: Saudi Arabic, Egyptian Arabic, Moroccan Darija, Gulf Arabic, Iraqi Arabic, Standard English, and Arabizi.','- The held-out paraphrase split reserves a separately written phrase for each theme and slice. It is controlled and synthetic; wrappers/templates and category wording remain limited.','- A separate leave-one-dialect-out stress test trains on six slices and evaluates the seventh.','', '## Baseline comparison','| Model | Accuracy | Macro-F1 |','|---|---:|---:|',f'| Word unigram + bigram Multinomial NB | {word["accuracy"]:.3f} | {word["macro_f1"]:.3f} |',f'| Character 2–4-gram Multinomial NB | {char["accuracy"]:.3f} | {char["macro_f1"]:.3f} |','', '![Baseline comparison](model_comparison.svg)', '', '## Held-out paraphrase results by slice','| Slice | Macro-F1 |','|---|---:|']
for n in names: lines.append(f'| {n} | {by[n]["macro_f1"]:.3f} |')
lines += ['', '![Performance by dialect](dialect_scores.svg)', '', '## Leave-one-dialect-out stress test','Each run excludes one complete dialect/language slice from training. English and Arabizi are lexically different from Arabic-script dialects, so transfer is expected to be harder.', '', '| Held-out slice | Word Macro-F1 | Character Macro-F1 |','|---|---:|---:|']
for d,v in m['leave_one_dialect_out']['word'].items(): lines.append(f'| {d} | {v["macro_f1"]:.3f} | {m["leave_one_dialect_out"]["char"][d]["macro_f1"]:.3f} |')
lines += ['', '![Leave-one-dialect-out scores](dialect_generalization.svg)', '', '## Corpus balance and errors','![Theme balance](category_counts.svg)', '', '![Confusion matrix](confusion_matrix.svg)', '', '## Interpretation','- Character features outperform word n-grams on the controlled paraphrase split, suggesting spelling-fragment features help in this setting.','- Arabizi and English remain difficult when the entire slice is withheld. This is a data coverage issue, not evidence of broad multilingual capability.','- High scores on some Arabic dialect holdouts are partly explained by shared vocabulary in the synthetic corpus.','', '## CAMeLBERT fine-tuning','CAMeLBERT-Mix is the intended primary app model. The Colab notebook fine-tunes it on the project categories and reports Accuracy, Macro-F1, per-class scores, dialect slices, and a confusion matrix. That training has not yet been run; therefore this report contains no CAMeLBERT scores.','', '## Limitations and next experiments','1. Replace generated examples with a properly licensed dataset of real app reviews; document its source and date.','2. De-identify reviews and have human annotators apply a written label guide.','3. Split by app/source and duplicate cluster to test transfer without leakage.','4. Run the CAMeLBERT notebook in Colab with a GPU; compare it against these baselines on the same fixed split.','5. Report per-dialect metrics and inspect false positives before making performance claims.','', '> All reported values are measured by running the included baseline experiment on synthetic examples. They are not estimates of production performance.']
OUT.joinpath('experiment_report.md').write_text('\n'.join(lines)+'\n',encoding='utf-8')
